16	export const convertVisibilityToString = (visibility: Visibility) => {
17	  switch (visibility) {
18	    case Visibility.PUBLIC:
19	      return "PUBLIC";
20	    case Visibility.PROTECTED:
21	      return "PROTECTED";
22	    case Visibility.PRIVATE:
23	      return "PRIVATE";
24	    default:
25	      return "PRIVATE";
26	  }
27	};
