97	      blurred,
98	      openEditor,
99	      toggleBlurVisibility,
100	      openPreview,
101	    ],
102	  );
103	
104	  if (showEditor) {
105	    return (
106	      <MemoEditor
107	        autoFocus
108	        className="mb-2"
109	        cacheKey={`inline-memo-editor-${memoData.name}`}
