16	interface UseLinkMemoParams {
17	  isOpen: boolean;
18	  currentMemoName?: string;
19	  existingRelations: MemoRelation[];
20	  onAddRelation: (relation: MemoRelation) => void;
21	}
22	
23	export const useLinkMemo = ({ isOpen, currentMemoName, existingRelations, onAddRelation }: UseLinkMemoParams) => {
24	  const user = useCurrentUser();
25	  const [searchText, setSearchText] = useState("");
26	  const [isFetching, setIsFetching] = useState(true);
27	  const [fetchedMemos, setFetchedMemos] = useState<Memo[]>([]);
28	
29	  const filteredMemos = fetchedMemos.filter((memo) => memo.name !== currentMemoName);
30	
31	  const linkedMemoNames = useMemo(() => new Set(existingRelations.map((r) => r.relatedMemo?.name)), [existingRelations]);
32	
33	  const isAlreadyLinked = (memoName: string): boolean => linkedMemoNames.has(memoName);
34	
35	  useEffect(() => {
36	    if (isOpen) {
37	      setSearchText("");
38	    }
39	  }, [isOpen]);
40	
41	  useDebouncedEffect(
42	    async () => {
43	      if (!isOpen) return;
44	
45	      setIsFetching(true);
46	      try {
47	        const conditions: string[] = [];
48	        const creatorFilter = buildMemoCreatorFilter(user?.name ?? "");
49	        if (creatorFilter) {
50	          conditions.push(creatorFilter);
51	        }
52	        if (searchText) {
53	          conditions.push(`content.contains("${searchText}")`);
54	        }
55	        const { memos } = await memoServiceClient.listMemos({
56	          pageSize: DEFAULT_LIST_MEMOS_PAGE_SIZE,
57	          filter: conditions.join(" && "),
58	        });
59	        setFetchedMemos(memos);
60	      } catch (error) {
61	        console.error(error);
62	      } finally {
63	        setIsFetching(false);
64	      }
65	    },
66	    300,
67	    [isOpen, searchText],
68	  );
69	
70	  const addMemoRelation = (memo: Memo) => {
71	    const relation = create(MemoRelationSchema, {
72	      type: MemoRelation_Type.REFERENCE,
73	      relatedMemo: create(MemoRelation_MemoSchema, {
74	        name: memo.name,
75	        snippet: memo.snippet,
76	      }),
77	    });
78	    onAddRelation(relation);
79	  };
80	
81	  return {
82	    searchText,
83	    setSearchText,
84	    isFetching,
85	    filteredMemos,
86	    addMemoRelation,
87	    isAlreadyLinked,
88	  };
89	};
